function draw(){
  const xc=$('#xc').classList.contains('on'),xq=$('#xq').classList.contains('on');
  const a=cur.v,b=cur.p,c=xc||xq?0:cur.c,t=cur.total || (a+b+c);
  $('#ring').style.setProperty('--p',t);$('#rv').textContent=t+'%';
  $('#rs').textContent=t<15?'Looks mostly original. Passages pass integrity guidelines.':(cur.explanation || 'Significant overlap detected. Review highlighted passages.');
  $('#pa').textContent=a+'% exact overlap';$('#pb2').textContent=b+'% semantic similarity';$('#pc2').textContent=(xc||xq)?'excluded':cur.c+'% citations';

  // Render dynamic doc text and evidence if available
  if(cur.evidence && cur.evidence.length > 0){
    let docHtml = cur.doc_a_text ? cur.doc_a_text.slice(0, 1000) : '';
    let srcHtml = '';

    cur.evidence.slice(0, 3).forEach((ev, idx)=>{
      const tag = idx === 0 ? 'a' : (idx === 1 ? 'b' : 'c');
      const sent = ev.sentence_a || '';
      if(sent && docHtml.includes(sent)){
        docHtml = docHtml.replace(sent, `<span class="hl ${tag}" data-s="${tag}">${sent}</span>`);
      } else if (!docHtml) {
        docHtml += `<span class="hl ${tag}" data-s="${tag}">${sent}</span> `;
      }

      const typeLabel = ev.type || 'Match';
      const reasonLabel = ev.reason || 'Similarity detected';
      srcHtml += `<div class="s ${tag}" data-s="${tag}"><span class="mono">${typeLabel} · ${cur.doc_b_title || 'Corpus Reference'}</span><br><b>${reasonLabel}</b><div class="mono">${ev.score || 0}% match score</div></div>`;
    });

    if(docHtml) $('.card.doc').innerHTML = docHtml;
    srcHtml += `<button class="btn acid" style="width:100%" onclick="toast('Report exported to PDF')">Export PDF</button>`;
    $('.srcs').innerHTML = srcHtml;
  }

  $$('.hl[data-s=c]').forEach(h=>h.classList.toggle('off',xc||xq));
  $$('.s[data-s=c]').forEach(h=>h.classList.toggle('dim',xc||xq));

  $$('.hl,.s').forEach(el=>el.onclick=()=>{
    const k=el.dataset.s;
    $$('.s').forEach(s=>s.classList.toggle('on',s.dataset.s===k));
  });
}

