async function upload(f){
  $('#up').style.display='block';$('#fn').textContent=f.name;
  let p=10;
  $('#pb').style.width=p+'%';$('#pc').textContent=p+'%';$('#ps').textContent='uploading…';

  const formData = new FormData();
  formData.append('file', f);
  formData.append('title', f.name);
  formData.append('author', user || 'Student');

  const progressInterval = setInterval(()=>{
    if(p < 85){
      p += Math.round(5 + Math.random() * 8);
      $('#pb').style.width=Math.min(85, p)+'%';
      $('#pc').textContent=Math.min(85, p)+'%';
      if(p > 35 && p < 65) $('#ps').textContent='reading your passages…';
      if(p >= 65) $('#ps').textContent='comparing with ProtocolX ML model…';
    }
  }, 200);

  try {
    const response = await fetch(`${API_BASE}/api/upload`, {
      method: 'POST',
      body: formData
    });

    clearInterval(progressInterval);
    $('#pb').style.width='100%';$('#pc').textContent='100%';$('#ps').textContent='done';

    if(response.ok){
      const data = await response.json();
      toast('Document processed & scanned!');
      await fetchReports();
      setTimeout(()=>{
        $('#up').style.display='none';
        if(data.report_id){
          open_('SYN-' + data.report_id);
        } else if(reps[0]) {
          open_(reps[0].id);
        }
      }, 500);
    } else {
      toast('Upload failed: ' + response.statusText);
      $('#up').style.display='none';
    }
  } catch(err) {
    clearInterval(progressInterval);
    console.error('Upload error:', err);
    toast('Error connecting to backend API');
    $('#up').style.display='none';
  }
}
